class Solution:
    def sumOfEncryptedInt(self, nums: List[int]) -> int:
        total_sum = 0
        for num in nums:
            # Find the largest digit in the number
            largest_digit = 0
            for digit in num:
                if digit > largest_digit:
                    largest_digit = digit
            # Replace all digits with the largest digit
            encrypted = [str(digit) for digit in num]
            encrypted = [str(largest_digit) for digit in encrypted]
            total_sum += sum(int(digit) for digit in encrypted)
        return total_sum
