class Solution:
    def stringHash(self, s: str, k: int) -> str:
        n = len(s)
        result = []
        for i in range(0, n, k):
            substring = s[i:i+k]
            hash_sum = 0
            for char in substring:
                hash_sum += ord(char) - ord('a')
            hash_val = hash_sum % 26
            result.append(chr(hash_val + ord('a')))
        return "".join(result)
